// @FIGURE_CODE_BEGIN
var W = 1240, H = 480;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H);

var RED = '#e8564f', PINK = '#fbe3d8', BLUE = '#1f9ad6',
    GREY = '#b5b5b5', GREYF = '#eeeeee', HOT = '#f4511e', HOTF = '#fbcdb2';
var SERIF = 'Georgia, "Times New Roman", serif';

var root = draw.group();
var state = { x: 0.9, overlay: false, stage: 0, focus: null };

/* ---------- small helpers ---------- */
function T(s, x, y, size, o) {
  o = o || {};
  var t = root.text(String(s));
  t.font({ family: SERIF, size: size, anchor: o.anchor || 'middle',
           style: o.italic ? 'italic' : 'normal', weight: o.weight || 'normal' });
  t.fill(o.fill || '#000');
  t.attr({ x: x, y: y, 'dominant-baseline': 'middle' });
  t.children().forEach(function (c) { c.attr({ x: x, dy: 0 }); });
  if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': o.halo, 'stroke-linejoin': 'round' });
  return t;
}
function frac(num, den, cx, y, size, fill) {
  var a = T(num, cx, y - size * 0.62, size, { fill: fill });
  var b = T(den, cx, y + size * 0.72, size, { fill: fill });
  var w = 10;
  try { w = Math.max(a.bbox().width, b.bbox().width) + 10; } catch (e) { w = size * 3; }
  root.line(cx - w / 2, y, cx + w / 2, y).stroke({ color: fill || '#000', width: 1.4 });
}
function arrowHead(g, x, y, ang, size, color) {
  var p = [[x, y],
           [x - size * Math.cos(ang - 0.38), y - size * Math.sin(ang - 0.38)],
           [x - size * Math.cos(ang + 0.38), y - size * Math.sin(ang + 0.38)]];
  return g.polygon(p.map(function (a) { return a.join(','); }).join(' ')).fill(color);
}
function arcPathStr(cx, cy, r, a0, a1) {
  var x0 = cx + r * Math.cos(a0), y0 = cy - r * Math.sin(a0);
  var x1 = cx + r * Math.cos(a1), y1 = cy - r * Math.sin(a1);
  var large = (Math.abs(a1 - a0) > Math.PI) ? 1 : 0;
  var sweep = (a1 > a0) ? 0 : 1;
  return 'M ' + x0 + ' ' + y0 + ' A ' + r + ' ' + r + ' 0 ' + large + ' ' + sweep + ' ' + x1 + ' ' + y1;
}
function braceH(g, x1, x2, y, d) {
  var m = (x1 + x2) / 2;
  var p = 'M ' + x1 + ' ' + y + ' Q ' + x1 + ' ' + (y + d) + ' ' + (x1 + d) + ' ' + (y + d) +
          ' L ' + (m - d) + ' ' + (y + d) + ' Q ' + m + ' ' + (y + d) + ' ' + m + ' ' + (y + 2 * d) +
          ' Q ' + m + ' ' + (y + d) + ' ' + (m + d) + ' ' + (y + d) +
          ' L ' + (x2 - d) + ' ' + (y + d) + ' Q ' + x2 + ' ' + (y + d) + ' ' + x2 + ' ' + y;
  return g.path(p).fill('none').stroke({ color: '#000', width: 1.4, linejoin: 'round' });
}
function braceV(g, x, y1, y2, d) {
  var m = (y1 + y2) / 2;
  var p = 'M ' + x + ' ' + y1 + ' Q ' + (x + d) + ' ' + y1 + ' ' + (x + d) + ' ' + (y1 + d) +
          ' L ' + (x + d) + ' ' + (m - d) + ' Q ' + (x + d) + ' ' + m + ' ' + (x + 2 * d) + ' ' + m +
          ' Q ' + (x + d) + ' ' + m + ' ' + (x + d) + ' ' + (m + d) +
          ' L ' + (x + d) + ' ' + (y2 - d) + ' Q ' + (x + d) + ' ' + y2 + ' ' + x + ' ' + y2;
  return g.path(p).fill('none').stroke({ color: '#000', width: 1.4, linejoin: 'round' });
}
function angleMark(g, vx, by, x, r, col) {
  col = col || '#000';
  g.path(arcPathStr(vx, by, r, 0, Math.max(x, 0.04))).fill('none').stroke({ color: col, width: 1.3 });
  var ex = vx + r * Math.cos(x), ey = by - r * Math.sin(x);
  arrowHead(g, ex, ey, Math.atan2(-Math.cos(x), -Math.sin(x)), 7, col);
  var lx, ly;
