  else { lx = vx + (r + 15) * Math.cos(x / 2); ly = by - (r + 15) * Math.sin(x / 2); }
  T('x', lx, ly, 17, { italic: true, halo: 3 });
}

/* ---------- region colours / focus ---------- */
function colFor(kind) {
  if (state.focus === kind) return { s: HOT, f: HOTF, w: 2.8, arc: BLUE };
  if (state.focus) return { s: GREY, f: GREYF, w: 1.5, arc: GREY };
  return { s: RED, f: PINK, w: 2, arc: BLUE };
}
var POP = {
  tan: ['Circumscribed triangle — area tan x / 2',
    'Its vertical leg lies on the tangent line at (1, 0), so its height is tan x and its area is (1 · tan x)/2. Because this triangle completely contains the sector, tan x / 2 ≥ x / 2.'],
  sector: ['Circular sector — area x / 2',
    'A sector of angle x in a unit circle covers the fraction x/(2π) of the disc of area π, so its area is x/2. It contains the inscribed triangle and is contained by the tangent triangle.'],
  sin: ['Inscribed triangle — area sin x / 2',
    'Its base is the radius 1 and its height is the altitude sin x, so its area is sin x / 2. It lies inside the sector, which gives x / 2 ≥ sin x / 2.']
};
function interactive(el, kind) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) {
    var x = state.x, v;
    if (kind === 'tan') v = 'Tangent triangle: tan x / 2 = ' + (Math.tan(x) / 2).toFixed(3);
    else if (kind === 'sector') v = 'Sector: x / 2 = ' + (x / 2).toFixed(3);
    else v = 'Inscribed triangle: sin x / 2 = ' + (Math.sin(x) / 2).toFixed(3);
    showTooltip(v + '  (click to isolate)', e);
  });
  el.on('mouseleave', hideTooltip);
  el.on('click', function () {
    state.focus = (state.focus === kind) ? null : kind;
    render();
    if (state.focus) showPopup(POP[kind][0], POP[kind][1]); else hidePopup();
  });
}

/* ---------- left panel : the unit circle construction ---------- */
var O = { x: 200, y: 195 }, R = 100, TOPCLAMP = 34;
function drawLeft(x) {
