function shapeSin(g, vx, by, L, x, opacity, withBrace) {
  var c = colFor('sin');
  var ax = vx + L * Math.cos(x), ay = by - L * Math.sin(x);
  var poly = g.polygon([[vx, by], [vx + L, by], [ax, ay]].map(function (p) { return p.join(','); }).join(' '))
    .fill({ color: c.f, opacity: (opacity == null ? 1 : opacity) })
    .stroke({ color: c.s, width: c.w, linejoin: 'round' });
  g.path(arcPathStr(vx, by, L, 0, x)).fill('none')
    .stroke({ color: c.arc, width: 2.5, dasharray: '9,6', linecap: 'round' });
  g.line(ax, ay, ax, by).stroke({ color: RED, width: 1.5, dasharray: '5,4' });
